head.script:
scwin.btn_expDown_onclick = function(e) {
    ngmf.setOverLayer(this, "grd_gridView1", "", 295);
};
scwin.btn_expUp_onclick = function(e) {
    ngmf.setOverLayer(this, "grd_gridView2", "", 295);
};
scwin.btn_expRight_onclick = function(e) {
    ngmf.setOverLayer(this, "grd_gridView3", 1420, "");
};
scwin.btn_expLeft_onclick = function(e) {
    ngmf.setOverLayer(this, "grd_gridView4", 1420, "");
};
scwin.btn_expAll_onclick = function(e) {
    ngmf.setOverLayer(this, "grd_gridView6", 1420, 475);
};
scwin.checkVal = function() {
    return window.getComputedStyle(WebSquare.wUnit.getDomById($p.id + 'wframe1_grd_gridView2_scrollY_div')).getPropertyValue('overflow-y') == 'hidden';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 스크롤을 맨아래로 내린다.
    //1. In the browser, scroll down to the bottom.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wframe1_grd_gridView2_scrollY_div').scrollTop = 100");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 스크롤이 맨아래로 내려간다.
    //1. Scroll down to the bottom.
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('wframe1_grd_gridView2').getTopRowIndex()", "1");
    //WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 하단에 늘리기 버튼을 클릭한다.
    //2. Click the Increase button at the bottom.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wframe1_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 높이가 늘어나, 스크롤이 사라진다. (그전버전에서 스크롤이 계속 남아있었음 / 그림참고)
    //2. The height increases and the scroll disappears. (Scrolling remained in previous versions / see figure)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wframe1_grd_gridView2').style.height == '259px'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wframe1_grd_gridView2_scrollY_div').style.width == '0px'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    /******************************************************************************
     * 프로그램명	 : OverLayer 확대/축소/열림/닫힘 샘플 가이드
     * ProgramID	 : PG-0417_0418(PG-0417_0418.xml)
     * 작성자		 : 홍길동
     * 작성일		 : 2015-12-30
     * 변경로그		 : 2015-12-30 최초 작성.
     *******************************************************************************/
    if (!scwin.promise) {
        scwin.promise = {};
    }
    /**
     * 타이틀1 grid의 btn_expDown(아래로 확장) 버튼 클릭 이벤트
     */
    /**
     * 타이틀2 grid의 btn_expUp(위로 확장) 버튼 클릭 이벤트
     */
    /**
     * 타이틀3 grid의 btn_expRight(오른쪽으로 확장) 버튼 클릭 이벤트
     */
    /**
     * 타이틀4 grid의 btn_expLeft(왼쪽으로 확장) 버튼 클릭 이벤트
     */
    /**
     * 타이틀6 grid의 btn_expAll(전체로 확장) 버튼 클릭 이벤트
     */
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 02-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
